# check if bottom column k has 8s occupying rows matching top column shifted by something
# Check per-column pattern shift: does bot[:,c] equal top[:,c] shifted vertically?
for c in range(15):
    t = top[:,c]; b = bot[:,c]
    # find shift s where np.roll or flip matches
    best=None
    for s in range(-8,9):
        if s>=0: sh=np.concatenate([np.zeros(s,int), t[:8-s]])
        else: sh=np.concatenate([t[-s:], np.zeros(-s,int)])
        if (sh==b).all(): best=('shift',s);break
    if (t[::-1]==b).all(): best=('flip',)
    print(c, best, list(t), list(b))

cands = {
 'rot180': np.rot90(top,2),
 'fliplr': np.fliplr(top),
 'flipud': np.flipud(top),
 'transpose': top.T,
 'anti-transpose': np.rot90(top.T,2),
}
for name,c in cands.items():
    print(name, int((c!=bot).sum()))

for s in range(-7,8):
    if s>0: sh=np.vstack([np.zeros((s,15),int), top[:8-s]])
    elif s<0: sh=np.vstack([top[-s:], np.zeros((-s,15),int)])
    else: sh=top
    print(s, int((sh!=bot).sum()))
